+func writeSessionTokensJSON(w io.Writer, report sessionTokensReport) error {
+	enc := json.NewEncoder(w)
+	enc.SetIndent("", "  ")
+	if err := enc.Encode(report); err != nil {
+		return fmt.Errorf("failed to encode session token report: %w", err)
+	}
+	return nil
+}
