+	for _, signal := range signals {
+		fmt.Fprintf(w, "- %s: %d checkpoint%s", signal.Label, signal.Count, pluralSuffix(signal.Count))
+		if signal.Percent > 0 {
+			fmt.Fprintf(w, " (%d%%)", signal.Percent)
+		}
+		fmt.Fprintln(w)
+	}
