package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

var activeStatuses = map[string]bool{
	"creating":   true,
	"ready":      true,
	"prompting":  true,
	"pending":    true,
	"warming_up": true,
	"running":    true,
}

var trailNeedles = []string{
	"542",
	"547",
	"559",
	"019eaa2b-9f6e-70df-88d4-1f5c2fab58ec",
	"019eafa1-44a0-756c-8ce6-3b1b1c79bbe6",
	"019eb555-acdb-772b-a9d0-af714ef67de2",
	"tokens",
	"tokens-agent-brief",
	"tokens-profile",
	"Token usage diagnostics",
	"Token guidance and checkpoint comparison",
	"Token profile history diagnostics",
}

type row struct {
	ID        string
	Status    string
	Kind      string
	Title     string
	Trail     string
	Branch    string
	CreatedAt string
	UpdatedAt string
	Raw       map[string]any
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	repoID := "5be1c302-97d2-4cf4-8436-b001efe227e0"
	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if err != nil {
		fatalf("resolve data API token: %v", err)
	}

	client := api.NewClientWithBaseURL(token, api.BaseURL())
	path := "/api/v1/runs?repoId=" + url.QueryEscape(repoID) + "&limit=250"
	resp, err := client.Get(ctx, path)
	if err != nil {
		fatalf("GET %s: %v", path, err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 16<<20))
	if err != nil {
		fatalf("read response: %v", err)
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		fmt.Printf("HTTP %d\n%s\n", resp.StatusCode, strings.TrimSpace(string(body)))
		os.Exit(1)
	}

	var data any
	if err := json.Unmarshal(body, &data); err != nil {
		fatalf("decode JSON: %v", err)
	}

	runs := extractRuns(data)
	rows := make([]row, 0, len(runs))
	counts := map[string]int{}
	for _, run := range runs {
		r := summarize(run)
		rows = append(rows, r)
		counts[strings.ToLower(r.Status)]++
	}
	sort.SliceStable(rows, func(i, j int) bool {
		return maxTime(rows[i]) > maxTime(rows[j])
	})

	active := filter(rows, func(r row) bool {
		return activeStatuses[strings.ToLower(r.Status)]
	})
	relevant := filter(rows, func(r row) bool {
		return matchesTrail(r.Raw)
	})
	activeRelevant := filter(relevant, func(r row) bool {
		return activeStatuses[strings.ToLower(r.Status)]
	})

	fmt.Printf("repo_id: %s\n", repoID)
	fmt.Printf("runs_returned: %d\n", len(rows))
	fmt.Printf("status_counts: %s\n", formatCounts(counts))
	fmt.Printf("active_runs: %d\n", len(active))
	printRows("active_run_rows", active)
	fmt.Printf("token_trail_runs_returned: %d\n", len(relevant))
	printRows("token_trail_rows", relevant)
	fmt.Printf("token_trail_active_runs: %d\n", len(activeRelevant))
	printRows("token_trail_active_rows", activeRelevant)
}

func extractRuns(data any) []map[string]any {
	if arr, ok := data.([]any); ok {
		return mapArray(arr)
	}
	obj, ok := data.(map[string]any)
	if !ok {
		return nil
	}
	for _, key := range []string{"runs", "items", "data", "results"} {
		if arr, ok := obj[key].([]any); ok {
			return mapArray(arr)
		}
	}
	return nil
}

func mapArray(arr []any) []map[string]any {
	out := make([]map[string]any, 0, len(arr))
	for _, item := range arr {
		if obj, ok := item.(map[string]any); ok {
			out = append(out, obj)
		}
	}
	return out
}

func summarize(run map[string]any) row {
	return row{
		ID:        firstString(run, "id", "run_id", "runId"),
		Status:    firstString(run, "status", "state"),
		Kind:      firstString(run, "kind", "type", "name", "runner", "eval_type", "evalType"),
		Title:     firstString(run, "title", "display_name", "displayName", "label"),
		Trail:     firstString(run, "trail_number", "trailNumber", "trail_id", "trailId", "trail"),
		Branch:    firstString(run, "branch", "branch_name", "branchName", "head_branch", "headBranch"),
		CreatedAt: firstString(run, "created_at", "createdAt", "started_at", "startedAt"),
		UpdatedAt: firstString(run, "updated_at", "updatedAt", "completed_at", "completedAt", "finished_at", "finishedAt"),
		Raw:       run,
	}
}

func firstString(obj map[string]any, keys ...string) string {
	for _, key := range keys {
		if v, ok := obj[key]; ok {
			if s := anyString(v); s != "" {
				return s
			}
		}
	}
	return ""
}

func anyString(v any) string {
	switch typed := v.(type) {
	case string:
		return typed
	case float64:
		if typed == float64(int64(typed)) {
			return fmt.Sprintf("%d", int64(typed))
		}
		return fmt.Sprintf("%v", typed)
	case bool:
		return fmt.Sprintf("%t", typed)
	case map[string]any:
		for _, key := range []string{"number", "id", "name", "title", "branch"} {
			if v, ok := typed[key]; ok {
				if s := anyString(v); s != "" {
					return s
				}
			}
		}
	}
	return ""
}

func matchesTrail(v any) bool {
	switch typed := v.(type) {
	case string:
		for _, needle := range trailNeedles {
			if strings.Contains(strings.ToLower(typed), strings.ToLower(needle)) {
				return true
			}
		}
	case float64:
		return matchesTrail(anyString(typed))
	case []any:
		for _, item := range typed {
			if matchesTrail(item) {
				return true
			}
		}
	case map[string]any:
		for _, item := range typed {
			if matchesTrail(item) {
				return true
			}
		}
	}
	return false
}

func filter(rows []row, fn func(row) bool) []row {
	var out []row
	for _, r := range rows {
		if fn(r) {
			out = append(out, r)
		}
	}
	return out
}

func maxTime(r row) string {
	if r.UpdatedAt != "" {
		return r.UpdatedAt
	}
	return r.CreatedAt
}

func formatCounts(counts map[string]int) string {
	keys := make([]string, 0, len(counts))
	for key := range counts {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	parts := make([]string, 0, len(keys))
	for _, key := range keys {
		parts = append(parts, fmt.Sprintf("%s=%d", key, counts[key]))
	}
	return strings.Join(parts, ", ")
}

func printRows(label string, rows []row) {
	fmt.Printf("%s:\n", label)
	if len(rows) == 0 {
		fmt.Println("  (none)")
		return
	}
	for _, r := range rows {
		fmt.Printf("  - id=%s status=%s kind=%s trail=%s branch=%s title=%s created=%s updated=%s\n",
			empty(r.ID), empty(r.Status), empty(r.Kind), empty(r.Trail), empty(r.Branch), empty(r.Title), empty(r.CreatedAt), empty(r.UpdatedAt))
	}
}

func empty(s string) string {
	if strings.TrimSpace(s) == "" {
		return "-"
	}
	return strings.ReplaceAll(s, "\n", " ")
}

func fatalf(format string, args ...any) {
	fmt.Fprintf(os.Stderr, format+"\n", args...)
	os.Exit(1)
}

